export function Icon({ name, size = 16, className, ...rest }) {
  const markup = ICONS[name] || '';
  return (
    <svg
      viewBox="0 0 16 16"
      width={size}
      height={size}
      className={className}
      {...rest}
      dangerouslySetInnerHTML={{ __html: markup }}
    />
  );
}
